import { test, expect } from '@playwright/test';

test.describe('Card Number Validation - Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display error message when user enters an invalid card number', async ({ page }) => {
    // Setup: intercept the API call to validate card number
    await page.route('**/api/validate-card-number', (route) => {
      route.abort('failed');
    });

    // Intercept the API call with invalid card number
    await page.route('**/api/validate-card-number', (route) => {
      route.continue();
    });

    // Verify error message is visible
    const errorMessage = page.getByText('Invalid card number');
    await expect(errorMessage).toBeVisible();

    // Verify error class is applied
    const errorClass = page.getByTestId('error-class');
    await expect(errorClass).toBeVisible();

    // Verify error icon is displayed
    const errorIcon = page.getByTestId('error-icon');
    await expect(errorIcon).toBeVisible();

    // Verify error message is displayed in a specific container
    const errorContainer = page.getByTestId('error-container');
    await expect(errorContainer).toBeVisible();

    // Verify error message text is correct
    await expect(errorMessage).toContainText('Invalid card number');

    // Verify error message is styled appropriately
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify form is still present and can be interacted with
    const cardNumberInput = page.getByLabel('Card Number');
    await expect(cardNumberInput).toBeVisible();

    // Verify card number input has error state
    await expect(cardNumberInput).toHaveClass(/error-input/);

    // Verify submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();
  });

  test('should clear error message when user enters a valid card number', async ({ page }) => {
    // Setup: intercept the API call to validate card number
    await page.route('**/api/validate-card-number', (route) => {
      route.continue();
    });

    // Verify error message is visible initially
    const errorMessage = page.getByText('Invalid card number');
    await expect(errorMessage).toBeVisible();

    // Verify error class is applied
    const errorClass = page.getByTestId('error-class');
    await expect(errorClass).toBeVisible();

    // Verify error icon is displayed
    const errorIcon = page.getByTestId('error-icon');
    await expect(errorIcon).toBeVisible();

    // Verify error message is displayed in a specific container
    const errorContainer = page.getByTestId('error-container');
    await expect(errorContainer).toBeVisible();

    // Verify error message text is correct
    await expect(errorMessage).toContainText('Invalid card number');

    // Verify error message is styled appropriately
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify card number input is initially empty
    const cardNumberInput = page.getByLabel('Card Number');
    await expect(cardNumberInput).toHaveValue('');

    // Verify card number input has error state
    await expect(cardNumberInput).toHaveClass(/error-input/);

    // Enter a valid card number
    await cardNumberInput.fill('1234567890123456');

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify error class is no longer applied
    await expect(errorClass).not.toBeVisible();

    // Verify error icon is no longer displayed
    const errorIcon = page.getByTestId('error-icon');
    await expect(errorIcon).not.toBeVisible();

    // Verify error message is not present
    const errorMessage = page.getByText('Invalid card number');
    await expect(errorMessage).not.toBeVisible();

    // Verify error message is not styled
    await expect(errorMessage).not.toHaveClass(/error-message/);

    // Verify error message is cleared
    const errorContainer = page.getByTestId('error-container');
    await expect(errorContainer).not.toBeVisible();

    // Verify error message is cleared from DOM
    await expect(errorMessage).not.toBeVisible();

    // Verify error message is cleared from state
    const errorState = page.evaluate(() => {
      const error = document.querySelector('[data-testid="error-message"]');
      return error ? error.textContent : '';
    });
    await expect(errorState).toBe('');

    // Verify submit button is now enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();
  });
});
